<span class="line">    <span class="token keyword">const</span> <span class="token punctuation">[</span>updates<span class="token punctuation">,</span> setUpdates<span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token function">useState</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
